import { CommonModule } from '@angular/common';
import { Component, effect, ElementRef, input, OnInit, output, viewChildren } from '@angular/core';
import { FormControl, ReactiveFormsModule } from '@angular/forms';
import { TranslocoModule } from '@jsverse/transloco';
import { BaseEditable } from '../base-editable';

@Component({
  selector: 'editable-pin',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule, TranslocoModule],
  providers: BaseEditable.getValidableAccessorProvider(EditablePinComponent),
  templateUrl: './editable-pin.component.html',
  styleUrls: ['./editable-pin.component.scss'],
})
export class EditablePinComponent extends BaseEditable<string> {
  length = input<number>(6);
  numericOnly = input<boolean>(true);
  mask = input<boolean>(false);
  autoSubmit = input<boolean>(false);

  completed = output<string>();

  boxes: FormControl<string>[] = [];
  readonly boxInputs = viewChildren<ElementRef<HTMLInputElement>>('boxInput');

  constructor() {
    super();

    effect(() => {
      const val = this.value() ?? '';
      if (!this.boxes.length) return;
      this.boxes.forEach((box, i) => {
        const ch = val[i] ?? '';
        if (box.value !== ch) {
          box.patchValue(ch, { emitEvent: false });
        }
      });
    });

    effect(() => {
      const isDisabled = this.disabled();
      this.boxes.forEach((box) => {
        isDisabled ? box.disable({ emitEvent: false }) : box.enable({ emitEvent: false });
      });
    });
  }

  override ngOnInit(): void {
    this.boxes = Array.from({ length: this.length() }, () => new FormControl<string>('', { nonNullable: true }));
    super.ngOnInit();
    this.bind(this.boxes);
  }

  onKeyDown(event: KeyboardEvent, index: number): void {
    const isPrintable = event.key.length === 1 && !event.ctrlKey && !event.metaKey && !event.altKey;

    if (isPrintable && this.boxes[index].value) {
      this.boxes[index].patchValue('', { emitEvent: false });
      (event.target as HTMLInputElement).value = '';
    }

    switch (event.key) {
      case 'Backspace':
        event.preventDefault();
        if (this.boxes[index].value) {
          this.boxes[index].patchValue('', { emitEvent: false });
          this.emit();
        } else if (index > 0) {
          this.boxes[index - 1].patchValue('', { emitEvent: false });
          this.focusBox(index - 1);
          this.emit();
        }
        break;
      case 'ArrowLeft':
        if (index > 0) {
          event.preventDefault();
          this.focusBox(index - 1);
        }
        break;
      case 'ArrowRight':
        if (index < this.length() - 1) {
          event.preventDefault();
          this.focusBox(index + 1);
        }
        break;
    }
  }

  onInput(event: Event, index: number): void {
    const inputEl = event.target as HTMLInputElement;
    const char = inputEl.value.slice(-1);

    if (!char) {
      this.boxes[index].patchValue('', { emitEvent: false });
      this.emit();
      return;
    }

    if (this.numericOnly() && !/^\d$/.test(char)) {
      this.boxes[index].patchValue('', { emitEvent: false });
      inputEl.value = '';
      return;
    }

    this.boxes[index].patchValue(char, { emitEvent: false });
    this.emit();

    if (index < this.length() - 1) {
      this.focusBox(index + 1);
    }

    if (this.autoSubmit() && this.isComplete()) {
      this.completed.emit(this.currentValue());
    }
  }

  onPaste(event: ClipboardEvent, startIndex: number): void {
    event.preventDefault();
    const pasted = event.clipboardData?.getData('text') ?? '';
    const chars = pasted.replace(/\s/g, '').split('');

    let written = 0;
    for (let i = startIndex; i < this.length() && written < chars.length; i++) {
      const char = chars[written++];
      if (this.numericOnly() && !/^\d$/.test(char)) continue;
      this.boxes[i].patchValue(char, { emitEvent: false });
    }

    const nextEmpty = this.boxes.findIndex((b, i) => i >= startIndex && !b.value);
    this.focusBox(nextEmpty >= 0 ? nextEmpty : Math.min(startIndex + chars.length, this.length() - 1));
    this.emit();
  }

  onFocus(index: number): void {
    this.boxInputs()[index]?.nativeElement.select();
  }

  override validate(_: any) {
    const val = this.currentValue();
    const errs: Record<string, boolean> = {};

    if (val.length > 0 && val.length < this.length()) {
      errs['pinIncomplete'] = true;
    }
    if (this.numericOnly() && val && !/^\d+$/.test(val)) {
      errs['pinNumericOnly'] = true;
    }

    return Object.keys(errs).length > 0 ? errs : null;
  }

  private focusBox(index: number): void {
    this.boxInputs()[index]?.nativeElement.focus();
  }

  private emit(): void {
    this.updateValue(this.currentValue() || null);
  }

  private currentValue(): string {
    return this.boxes.map((b) => b.value).join('');
  }

  private isComplete(): boolean {
    return this.boxes.every((b) => !!b.value);
  }
}
